/**
 * Vwayaj Ayiti — the department pack: the 10 departments in journey order, their chef-lieu, a few kid-sized
 * facts and ~13–15 multiple-choice questions each, plus a handful of "special" questions for the dated events.
 * Same style rules as content/bank/BRIEF.md (Kreyòl first, short sentences, only well-established facts).
 * Every question is `review` until a Haitian proofreader approves it in the admin panel.
 */
import type { AgeBand, CategoryId, Difficulty, LocalizedText, Question } from '../types.js';

export type DepartmentId = 'lwes' | 'sides' | 'sid' | 'grandans' | 'nip' | 'sant' | 'latibonit' | 'nodwes' | 'no' | 'nodes';

export interface DepartmentPack {
  id: DepartmentId;
  name: LocalizedText;
  chefLieu: LocalizedText;
  facts: LocalizedText[];
  questions: Question[];
}

// ─── compact authoring helpers ───────────────────────────────────────────────
/** A = every band, B = 9-11 + 12-14, C = 12-14 only, Y = 6-8 + 9-11 */
type Band = 'A' | 'B' | 'C' | 'Y';
const BANDS: Record<Band, AgeBand[]> = { A: ['6-8', '9-11', '12-14'], B: ['9-11', '12-14'], C: ['12-14'], Y: ['6-8', '9-11'] };
type Opt = string | [string, string];
type Raw = [d: Difficulty, ages: Band, topic: string, ht: string, fr: string, opts: Opt[], a: number, ex: string, exFr: string];

const CAT: Record<string, CategoryId> = { istwa: 'istwa', moun: 'istwa', kilti: 'kilti', manje: 'kilti' };
const opt = (o: Opt): LocalizedText => (typeof o === 'string' ? { ht: o, fr: o } : { ht: o[0], fr: o[1] });
function build(prefix: string, rows: Raw[]): Question[] {
  return rows.map(([d, band, topic, ht, fr, opts, a, ex, exFr], i) => ({
    id: `vw-${prefix}-${String(i + 1).padStart(2, '0')}`,
    category: CAT[topic] ?? 'jewografi',
    difficulty: d,
    ages: BANDS[band],
    prompt: { ht, fr },
    options: opts.map(opt),
    answer: a,
    explain: { ht: ex, fr: exFr },
    status: 'review',
    topic: `vwayaj-${topic}`,
  }));
}
const T = (ht: string, fr: string): LocalizedText => ({ ht, fr });

